from pathlib import Path
import json
p=Path('README.md');s=p.read_text(encoding='utf-8-sig');s+='\n## Coverflow quick selection\nWith the mouse over expanded Coverflow, tap Space to toggle the current image. Hold Space and scroll to add the starting image and every crossed image to the selection. Reversing direction does not deselect images. Release Space, move the pointer out, press Escape or switch windows to stop. Text inputs, open dialogs and busy processing do not consume Space. The selection is shared with the grid, Export and Process.\n';p.write_text(s,encoding='utf-8')
report={'unitTests':5,'browserChecks':{'rangeForwardThenReverse':{'active':'image-4','selected':['image-2','image-3','image-4','image-5','image-6']},'keyRepeat':'toggles only once','outsideArea':{'defaultPrevented':False,'selected':[]},'inputFocus':{'defaultPrevented':False,'selected':[]},'windowBlur':'held state released; subsequent wheel browses without extending selection','nativeSpaceOnNextButton':'image-4 stays active while Space adds/removes image-4; no unintended Next activation'},'userProjectsChanged':False,'paidRequests':0}
Path('docs/verification/coverflow-quick-selection.json').write_text(json.dumps(report,indent=2),encoding='utf-8')
